// every animal by id: { name, kind (its kind's name), coat, lvl, props, desc, fem }
function stableList(kinds, first) {
  const out = {};
  kinds.forEach((k, i) => {
    const lvl = i + 1;
    if (i === 0) for (const [id, x] of Object.entries(first)) out[id] = { ...x, kind: k.name, lvl, props: x.props || k.props, fem: false };
    else for (const [c, adj] of k.coats) out[`${k.id}-${c}`] = { name: `${k.name} ${adj}`, kind: k.name, coat: adj, lvl, props: k.props, desc: k.desc, fem: !!k.fem, species: k.id };
  });
  return out;
}
export const PETS = stableList(PET_KINDS, DOGS);
export const MOUNTS = stableList(MOUNT_KINDS, HORSES);
